entries[406106] = { ["name"] = "Draconic Phial Cauldron", ["text"] = "3 sec cast\nReagents:\nDracothyst (2), Dragon's Alchemical Solution (60), Awakened Frost (5), Awakened Air (5), Hochenblume (240), Saxifrage (80), Bubble Poppy (80), Writhebark (80)\nOptional Reagents:\nAlchemical Catalyst (#94) , Lesser Illustrious Insight (#92)\nDrop:\nThe Amalgamation Chamber\nZone:\nAberrus, the Shadowed Crucible\nRecipe:\nPurchasable on the Auction House\n\nDraconic Phial Cauldron\nBinds to Warband\n\nUse: Place a cauldron that allows party and raid members to take phials of their choosing from among the recipes known by the alchemist who placed the cauldron.\n\nThe cauldron lasts for 5 min and has 40 charges; each charge gives 2 phials.\n61" }
